// ---------------------------------------------------------------------------
// CompileLlvm — Phase 16 effectful-compilation tests
//
// Sibling of `compile-wasm-effects.test.ts`. Exercises:
//
//   1. The lowering — `$effect:<Class>:<method>` sentinel calls produce
//      `declare ptr @fenel_<Class>_<method>(ptr, …)` extern declarations +
//      corresponding `call` instructions. The matching `LlvmEffectImport`
//      metadata appears in `LlvmModule.effectImports`.
//   2. The C runtime shim — auto-generated per-`(Class, method)` shim
//      functions dispatch through the global handler registry
//      (`fenel_lookup_handler` → `m->invoke(env, args, n)`). The bootstrap
//      uses the global-registry ABI variant per `design/effectful-
//      compilation.md` ("explicit %ctx threading lands when a real
//      performance case forces it").
//   3. The end-to-end loop — when `clang` is available: compile the
//      LLVM IR + the C shim into a shared object, load it via Bun's
//      FFI, register JS-side handlers via `fenel_register_handler`, and
//      assert the LLVM-emitted entry function returns byte-identical
//      results to the engine's interpretation of the same body.
//
// Test cases mirror the Phase 15 brief:
//
//      addAndPersist(a, b) : Number requires [HasStateIO@scratch]
//      randomLessThan(n) : Bool requires [HasCryptoRandom@test]
//
// Toolchain gating: `Bun.which("clang")` detects the C compiler; the
// compile + execute arc runs only when present. When absent (typical CI
// on lean images, or Windows without LLVM installed), the test arc skips
// with a `console.warn` per case, matching `compile-llvm.test.ts`'s
// `llvm-as` posture. The IR-shape + shim-generator tests always run.
//
// Brief: `prompts/phase-16-llvm-effect-lowering.md`. Design notes:
// `design/effectful-compilation.md` (Wasm sibling = Phase 15).
// ---------------------------------------------------------------------------

import { describe, it, expect } from "vitest";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import {
  compileFenelToLlvmNative,
  serializeLlvmModuleNative,
} from "./modules/compile-llvm";
import type { CompileSource } from "./compilable";
import { positionalCompileFieldSlots } from "./compile-field-slots";
import type { LlvmEffectImport } from "./ir/llvm-ast";

// ---------------------------------------------------------------------------
// Toolchain detection
// ---------------------------------------------------------------------------

function whichSafe(name: string): string | null {
  try {
    const bun = (globalThis as { Bun?: { which: (n: string) => string | null } }).Bun;
    return bun?.which(name) ?? null;
  } catch {
    return null;
  }
}

const CLANG_PATH = whichSafe("clang");
const HAS_CLANG = CLANG_PATH !== null;

// ---------------------------------------------------------------------------
// Test helpers
// ---------------------------------------------------------------------------

function src(name: string, paramNames: string[], body: unknown, requires?: string[]): CompileSource {
  return {
    name,
    params: positionalCompileFieldSlots(paramNames),
    body,
    ...(requires !== undefined ? { requires } : {}),
  };
}

/**
 * Auto-generate the per-(Class, method) C shim from a module's effect-
 * import metadata. One C function per entry, dispatching through the
 * runtime registry (`fenel_lookup_handler` → `m->invoke(env, args, n)`).
 *
 * The result is the body of a `.c` file that links alongside `runtime/
 * llvm-rt.c` + the LLVM-emitted IR via `clang -shared`.
 */
export function generateEffectShimC(imports: readonly LlvmEffectImport[]): string {
  const lines: string[] = [
    "/* Auto-generated by compile-llvm-effects.test.ts. One C shim per",
    " * effect-dispatch import in the compiled module. Each shim looks up",
    " * its handler in the global registry and trampolines through the",
    " * registered (env, args, n) callback. */",
    "#include <stdint.h>",
    "#include <stdlib.h>",
    "",
    "typedef void *(*FenelHandlerFn)(void *env, void **args, int n);",
    "typedef struct {",
    "  char *key;",
    "  FenelHandlerFn invoke;",
    "  void *env;",
    "} FenelHandlerEntry;",
    "",
    "extern FenelHandlerEntry *fenel_lookup_handler(const char *key);",
    "",
  ];
  for (const imp of imports) {
    const key = `${imp.typeName}:${imp.methodName}`;
    const params: string[] = [];
    for (let i = 0; i < imp.arity; i++) params.push(`void *a${i}`);
    const sig = params.length > 0 ? params.join(", ") : "void";
    lines.push(`void *${imp.symbol}(${sig}) {`);
    lines.push(`  FenelHandlerEntry *m = fenel_lookup_handler("${key}");`);
    lines.push(`  if (m == NULL) return NULL;`);
    if (imp.arity === 0) {
      lines.push(`  return m->invoke(m->env, NULL, 0);`);
    } else {
      const initList: string[] = [];
      for (let i = 0; i < imp.arity; i++) initList.push(`a${i}`);
      lines.push(`  void *args[${imp.arity}] = { ${initList.join(", ")} };`);
      lines.push(`  return m->invoke(m->env, args, ${imp.arity});`);
    }
    lines.push(`}`);
    lines.push("");
  }
  return lines.join("\n");
}

// ---------------------------------------------------------------------------
// 1. IR-level — `$effect:` sentinels lower to extern + call + populate
//    `effectImports` metadata.
// ---------------------------------------------------------------------------

describe("Phase 16 — `$effect:` sentinel + LLVM lowering", () => {
  it("lowerToLlvmAst emits a `fenel_HasStateIO_set` extern + call for a body that uses it", () => {
    const compiled = compileFenelToLlvmNative(
      src(
        "persistSum",
        ["a", "b"],
        {
          do: [
            { let: { sum: { "+": [{ var: "a" }, { var: "b" }] } } },
            { call: ["$effect:HasStateIO:set", "result", { var: "sum" }] },
            { var: "sum" },
          ],
        },
        ["HasStateIO@scratch"],
      ),
    );
    expect(compiled.$tag).toBe("Ok");
    if (compiled.$tag !== "Ok") return;
    const mod = compiled._0;
    const setDecl = mod.declarations.find((d) => d.name === "fenel_HasStateIO_set");
    expect(setDecl).toBeDefined();
    expect(setDecl!.returnType.$tag).toBe("Ptr");
    expect(setDecl!.params.map((p) => p.paramType.$tag)).toEqual(["Ptr", "Ptr"]);
    // Structured metadata.
    expect(mod.effectImports?.length).toBe(1);
    expect(mod.effectImports?.[0]).toMatchObject({
      typeName: "HasStateIO",
      methodName: "set",
      arity: 2,
      symbol: "fenel_HasStateIO_set",
    });
    // The string arg "result" interned in the per-module pool.
    expect(mod.stringPool).toEqual(["result"]);
  });

  it("multiple effect classes share `effectImports` + dedupe by (Class, method, arity)", () => {
    const compiled = compileFenelToLlvmNative(
      src(
        "introspect",
        ["v"],
        {
          do: [
            { call: ["$effect:HasStateIO:set", "a", { var: "v" }] },
            { call: ["$effect:HasStateIO:set", "b", { var: "v" }] }, // dedupes
            { call: ["$effect:HasCryptoRandom:nextNumber"] },
            { var: "v" },
          ],
        },
        ["HasStateIO@scratch", "HasCryptoRandom@scratch"],
      ),
    );
    expect(compiled.$tag).toBe("Ok");
    if (compiled.$tag !== "Ok") return;
    const mod = compiled._0;
    const symbols = (mod.effectImports ?? []).map((e) => e.symbol).sort();
    expect(symbols).toEqual(["fenel_HasCryptoRandom_nextNumber", "fenel_HasStateIO_set"]);
    // Both extern declarations appear, no duplicates.
    const setDecls = mod.declarations.filter((d) => d.name === "fenel_HasStateIO_set");
    expect(setDecls.length).toBe(1);
    const nextDecls = mod.declarations.filter((d) => d.name === "fenel_HasCryptoRandom_nextNumber");
    expect(nextDecls.length).toBe(1);
  });

  it("string CeLits intern into the per-module string pool + emit @.str.<i> private constants", () => {
    const compiled = compileFenelToLlvmNative(
      src(
        "twoKeys",
        ["v"],
        {
          do: [
            { call: ["$effect:HasStateIO:set", "alpha", { var: "v" }] },
            { call: ["$effect:HasStateIO:set", "beta", { var: "v" }] },
            { call: ["$effect:HasStateIO:set", "alpha", { var: "v" }] }, // dedupes
            { var: "v" },
          ],
        },
        ["HasStateIO@scratch"],
      ),
    );
    expect(compiled.$tag).toBe("Ok");
    if (compiled.$tag !== "Ok") return;
    const mod = compiled._0;
    expect(mod.stringPool).toEqual(["alpha", "beta"]);
    // The serialiser emits private constants with the right shapes.
    const ir = serializeLlvmModuleNative(mod);
    expect(ir.$tag).toBe("Ok");
    if (ir.$tag !== "Ok") return;
    expect(ir._0).toContain(`@.str.0 = private unnamed_addr constant [6 x i8] c"alpha\\00"`);
    expect(ir._0).toContain(`@.str.1 = private unnamed_addr constant [5 x i8] c"beta\\00"`);
    // The body references them via global ref + the lit_string helper.
    expect(ir._0).toContain("declare ptr @fenel_lit_string(ptr, i64)");
    expect(ir._0).toContain("call ptr @fenel_lit_string(ptr @.str.0, i64 5)");
    expect(ir._0).toContain("call ptr @fenel_lit_string(ptr @.str.1, i64 4)");
  });

  it("effect-call args are coerced to ptr — numbers via `fenel_box_num`, booleans via `fenel_box_bool`", () => {
    const compiled = compileFenelToLlvmNative(
      src(
        "boxArgs",
        ["a", "b"],
        {
          do: [
            // sum is DOM_DOUBLE; passing it as effect arg requires box_num.
            { let: { sum: { "+": [{ var: "a" }, { var: "b" }] } } },
            { call: ["$effect:HasStateIO:set", "k", { var: "sum" }] },
            { var: "sum" },
          ],
        },
        ["HasStateIO@scratch"],
      ),
    );
    expect(compiled.$tag).toBe("Ok");
    if (compiled.$tag !== "Ok") return;
    const mod = compiled._0;
    const ir = serializeLlvmModuleNative(mod);
    expect(ir.$tag).toBe("Ok");
    if (ir.$tag !== "Ok") return;
    expect(ir._0).toContain("declare ptr @fenel_box_num(double)");
    // The `sum` let-binding holds the f64 from the fadd; the box_num call
    // boxes it before the effect-call boundary. Let-bound names lower to
    // auto-numbered SSA temporaries (`%t<n>`), so we match the shape, not
    // the name.
    expect(ir._0).toMatch(/call ptr @fenel_box_num\(double %t\d+\)/);
    expect(ir._0).toMatch(/call ptr @fenel_HasStateIO_set\(ptr %t\d+, ptr %t\d+\)/);
  });

  it("effect-call results unbox back to double when consumed in numeric position", () => {
    // randomLessThan: `nextNumber()` returns ptr; lt requires double, so
    // unbox_num is inserted at the boundary.
    const compiled = compileFenelToLlvmNative(
      src(
        "randomLessThan",
        ["n"],
        { "<": [{ call: ["$effect:HasCryptoRandom:nextNumber"] }, { var: "n" }] },
        ["HasCryptoRandom@test"],
      ),
    );
    expect(compiled.$tag).toBe("Ok");
    if (compiled.$tag !== "Ok") return;
    const mod = compiled._0;
    const ir = serializeLlvmModuleNative(mod);
    expect(ir.$tag).toBe("Ok");
    if (ir.$tag !== "Ok") return;
    expect(ir._0).toContain("declare double @fenel_unbox_num(ptr)");
    expect(ir._0).toContain("call double @fenel_unbox_num(");
    expect(ir._0).toContain("call ptr @fenel_HasCryptoRandom_nextNumber()");
    // Function returns i1 (boolean).
    expect(ir._0).toContain("define i1 @randomLessThan(double %n)");
  });

  it("pure programs are unaffected — no effect imports in `effectImports`", () => {
    const compiled = compileFenelToLlvmNative(
      src("add", ["a", "b"], { "+": [{ var: "a" }, { var: "b" }] }),
    );
    expect(compiled.$tag).toBe("Ok");
    if (compiled.$tag !== "Ok") return;
    const mod = compiled._0;
    // Phase 21.10 — wire-shape normalisation is gone; empty effectImports
    // / stringPool flow through as `[]` (no longer stripped to `undefined`).
    expect(mod.effectImports).toEqual([]);
    expect(mod.stringPool).toEqual([]);
  });
});

// ---------------------------------------------------------------------------
// 2. Shim generator — `generateEffectShimC` produces well-formed C
// ---------------------------------------------------------------------------

describe("Phase 16 — generateEffectShimC", () => {
  it("emits one trampoline per (Class, method, arity) triple", () => {
    const shim = generateEffectShimC([
      { typeName: "HasStateIO", methodName: "set", arity: 2, symbol: "fenel_HasStateIO_set" },
      { typeName: "HasStateIO", methodName: "get", arity: 1, symbol: "fenel_HasStateIO_get" },
      {
        typeName: "HasCryptoRandom",
        methodName: "nextNumber",
        arity: 0,
        symbol: "fenel_HasCryptoRandom_nextNumber",
      },
    ]);
    expect(shim).toContain(
      "void *fenel_HasStateIO_set(void *a0, void *a1) {",
    );
    expect(shim).toContain(`fenel_lookup_handler("HasStateIO:set")`);
    expect(shim).toContain("void *args[2] = { a0, a1 };");
    expect(shim).toContain("void *fenel_HasStateIO_get(void *a0) {");
    expect(shim).toContain("void *fenel_HasCryptoRandom_nextNumber(void) {");
    expect(shim).toContain(`fenel_lookup_handler("HasCryptoRandom:nextNumber")`);
    expect(shim).toContain("return m->invoke(m->env, NULL, 0);");
  });

  it("empty input emits header-only output (no trampolines)", () => {
    const shim = generateEffectShimC([]);
    expect(shim).toContain("typedef void *(*FenelHandlerFn)");
    expect(shim).not.toMatch(/void \*fenel_/);
  });
});

// ---------------------------------------------------------------------------
// 3. End-to-end — compile + link + execute via `clang -shared` + Bun FFI
//
// The load-bearing demonstration: when `clang` is available, the LLVM-
// emitted IR + the per-module shim + `runtime/llvm-rt.c` link into a
// shared object. Bun FFI loads it, the test registers JS handlers, and
// invokes the entry function. Results match the engine's interpretation
// under the same mocked state.
//
// Skipped with a `console.warn` when `clang` is absent (Phase 14's
// `llvm-as`-gated posture). The structural tests above gate IR validity
// in that case.
// ---------------------------------------------------------------------------

const REPO_ROOT = path.resolve(__dirname, "..", "..", "..", "..");
const RUNTIME_C = path.join(REPO_ROOT, "runtime", "llvm-rt.c");

/**
 * Build a shared object from (LLVM IR text + per-module C shim +
 * `runtime/llvm-rt.c`). Returns the path to the produced library.
 *
 * Throws with the C compiler's stderr on failure.
 */
function compileToSharedObject(name: string, irText: string, shimC: string): string {
  if (CLANG_PATH === null) throw new Error("clang not available");
  const bun = (globalThis as {
    Bun?: {
      spawnSync: (cmd: string[], opts?: {
        stderr?: "pipe" | "inherit" | "ignore";
        stdout?: "pipe" | "inherit" | "ignore";
      }) => { exitCode: number; stdout: Uint8Array; stderr: Uint8Array };
    };
  }).Bun;
  if (bun === undefined) throw new Error("Bun not available");

  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), `fenel-llvm-${name}-`));
  const irPath = path.join(tmpDir, `${name}.ll`);
  const shimPath = path.join(tmpDir, `${name}_shim.c`);
  // Pick the platform's shared-library suffix.
  const ext = process.platform === "darwin" ? "dylib" : process.platform === "win32" ? "dll" : "so";
  const soPath = path.join(tmpDir, `lib${name}.${ext}`);
  fs.writeFileSync(irPath, irText);
  fs.writeFileSync(shimPath, shimC);

  const cmd = [
    CLANG_PATH,
    "-shared",
    "-fPIC",
    "-O0",
    "-o", soPath,
    shimPath,
    irPath,
    RUNTIME_C,
  ];
  // On Windows, mingw-style export-all-symbols gives Bun's dlopen access
  // to the symbols. For MSVC-target clang this flag is ignored; the test
  // will surface a clear "symbol not found" error from dlopen if the build
  // uses the MSVC ABI. The `cl.exe` path is explicitly out of scope per
  // the brief.
  if (process.platform === "win32") cmd.push("-Wl,--export-all-symbols");

  const result = bun.spawnSync(cmd, { stderr: "pipe", stdout: "pipe" });
  if (result.exitCode !== 0) {
    const stderr = new TextDecoder().decode(result.stderr);
    const stdout = new TextDecoder().decode(result.stdout);
    throw new Error(
      `clang failed (exit ${result.exitCode}):\nstderr:\n${stderr}\nstdout:\n${stdout}\nIR:\n${irText}\nSHIM:\n${shimC}`,
    );
  }
  return soPath;
}

describe("Phase 16 — end-to-end via clang + Bun FFI", () => {
  if (!HAS_CLANG) {
    it.skip("clang not available — exec arc skipped (structural tests above gate IR validity)", () => {
      // Surface the skip reason via console.warn so CI logs explain the
      // missing coverage. Same posture as `compile-llvm.test.ts`'s
      // `llvm-as`-absent skip.
      console.warn(
        "[compile-llvm-effects.test] `clang` not on PATH — skipping the LLVM compile + execute arc. " +
          "The structural / IR-shape tests above gate validity in this configuration. " +
          "Install LLVM (https://releases.llvm.org/) or set up `clang` to enable the full bootstrap.",
      );
    });
    return;
  }

  it("addAndPersist(a, b) — returns sum, persists side-effect via HasStateIO.set", async () => {
    const ffi = await import("bun:ffi");
    const { dlopen, FFIType, JSCallback, read, CString } = ffi;
    type Pointer = ReturnType<typeof ffi.ptr>;

    const body = {
      do: [
        { let: { sum: { "+": [{ var: "a" }, { var: "b" }] } } },
        { call: ["$effect:HasStateIO:set", "result", { var: "sum" }] },
        { var: "sum" },
      ],
    };
    const compiled = compileFenelToLlvmNative(
      src("addAndPersist", ["a", "b"], body, ["HasStateIO@scratch"]),
    );
    expect(compiled.$tag).toBe("Ok");
    if (compiled.$tag !== "Ok") return;
    const mod = compiled._0;
    const irText = (() => {
      const r = serializeLlvmModuleNative(mod);
      if (r.$tag !== "Ok") throw new Error(`serialize failed: ${r._0}`);
      return r._0;
    })();
    const shimC = generateEffectShimC(mod.effectImports ?? []);
    const soPath = compileToSharedObject("addAndPersist", irText, shimC);

    const lib = dlopen(soPath, {
      addAndPersist: { args: [FFIType.f64, FFIType.f64], returns: FFIType.f64 },
      fenel_register_handler: {
        args: [FFIType.cstring, FFIType.ptr, FFIType.ptr],
        returns: FFIType.void,
      },
      fenel_reset_handlers: { args: [], returns: FFIType.void },
    });

    // Storage map captured by the JS callback.
    const storage = new Map<string, number>();
    const setCallback = new JSCallback(
      (_envPtr: Pointer | null, argsPtr: Pointer | null, _n: number): null => {
        // argsPtr is a Pointer to an array of `void *` (8 bytes each on
        // 64-bit). Read both pointers, then decode each via its expected
        // type (key = C-string, value = boxed double).
        const keyPtr = read.ptr(argsPtr as Pointer, 0) as Pointer;
        const valPtr = read.ptr(argsPtr as Pointer, 8) as Pointer;
        const key = new CString(keyPtr).toString();
        const val = read.f64(valPtr, 0);
        storage.set(key, val);
        return null;
      },
      { args: [FFIType.ptr, FFIType.ptr, FFIType.i32], returns: FFIType.ptr },
    );

    const keyBuf = Buffer.from("HasStateIO:set\0");
    lib.symbols.fenel_register_handler(keyBuf, setCallback.ptr, null);
    try {
      const result = lib.symbols.addAndPersist(3, 5);
      expect(result).toBe(8);
      expect(storage.get("result")).toBe(8);

      const result2 = lib.symbols.addAndPersist(-7, 7);
      expect(result2).toBe(0);
      expect(storage.get("result")).toBe(0);

      const result3 = lib.symbols.addAndPersist(-3, -4);
      expect(result3).toBe(-7);
      expect(storage.get("result")).toBe(-7);
    } finally {
      lib.symbols.fenel_reset_handlers();
      setCallback.close();
      lib.close();
      try {
        fs.rmSync(path.dirname(soPath), { recursive: true, force: true });
      } catch {
        // Best-effort cleanup; safe to ignore if the OS holds the file.
      }
    }
  });

  it("randomLessThan(n) — comparison with effect call in branch-decision position", async () => {
    const ffi = await import("bun:ffi");
    const { dlopen, FFIType, JSCallback, ptr } = ffi;
    type Pointer = ReturnType<typeof ptr>;

    const body = { "<": [{ call: ["$effect:HasCryptoRandom:nextNumber"] }, { var: "n" }] };
    const compiled = compileFenelToLlvmNative(
      src("randomLessThan", ["n"], body, ["HasCryptoRandom@test"]),
    );
    expect(compiled.$tag).toBe("Ok");
    if (compiled.$tag !== "Ok") return;
    const mod = compiled._0;
    const irText = (() => {
      const r = serializeLlvmModuleNative(mod);
      if (r.$tag !== "Ok") throw new Error(`serialize failed: ${r._0}`);
      return r._0;
    })();
    const shimC = generateEffectShimC(mod.effectImports ?? []);
    const soPath = compileToSharedObject("randomLessThan", irText, shimC);

    const lib = dlopen(soPath, {
      randomLessThan: { args: [FFIType.f64], returns: FFIType.bool },
      fenel_register_handler: {
        args: [FFIType.cstring, FFIType.ptr, FFIType.ptr],
        returns: FFIType.void,
      },
      fenel_reset_handlers: { args: [], returns: FFIType.void },
    });

    // Deterministic queue — fed back to LLVM as boxed-double pointers.
    const queue = [0.1, 0.5, 0.9];
    let idx = 0;
    // Per-callback scratch buffer holding the boxed-double return value.
    // Lifetime: the buffer is held by the closure for as long as the
    // JSCallback is open, so the pointer stays valid across the LLVM
    // unbox call that immediately follows.
    const scratch = Buffer.alloc(8);
    const nextNumberCallback = new JSCallback(
      (_envPtr: Pointer | null, _argsPtr: Pointer | null, _n: number): Pointer => {
        const v = queue[idx % queue.length]!;
        idx++;
        scratch.writeDoubleLE(v, 0);
        return ptr(scratch);
      },
      { args: [FFIType.ptr, FFIType.ptr, FFIType.i32], returns: FFIType.ptr },
    );

    const keyBuf = Buffer.from("HasCryptoRandom:nextNumber\0");
    lib.symbols.fenel_register_handler(keyBuf, nextNumberCallback.ptr, null);
    try {
      // Each call dequeues one number from the mock and compares against n.
      expect(lib.symbols.randomLessThan(0.5)).toBe(true); // 0.1 < 0.5
      expect(lib.symbols.randomLessThan(0.5)).toBe(false); // 0.5 < 0.5 false
      expect(lib.symbols.randomLessThan(0.5)).toBe(false); // 0.9 < 0.5 false
    } finally {
      lib.symbols.fenel_reset_handlers();
      nextNumberCallback.close();
      lib.close();
      try {
        fs.rmSync(path.dirname(soPath), { recursive: true, force: true });
      } catch {
        // Best-effort cleanup.
      }
    }
  });

  it("multi-class effect dispatch — HasStateIO + HasCryptoRandom in one body", async () => {
    const ffi = await import("bun:ffi");
    const { dlopen, FFIType, JSCallback, ptr, read, CString } = ffi;
    type Pointer = ReturnType<typeof ptr>;

    const body = {
      do: [
        { let: { r: { call: ["$effect:HasCryptoRandom:nextNumber"] } } },
        { call: ["$effect:HasStateIO:set", "lastRandom", { var: "r" }] },
        { var: "r" },
      ],
    };
    const compiled = compileFenelToLlvmNative(
      src("captureRandom", [], body, ["HasCryptoRandom@test", "HasStateIO@test"]),
    );
    expect(compiled.$tag).toBe("Ok");
    if (compiled.$tag !== "Ok") return;
    const mod = compiled._0;
    const irText = (() => {
      const r = serializeLlvmModuleNative(mod);
      if (r.$tag !== "Ok") throw new Error(`serialize failed: ${r._0}`);
      return r._0;
    })();
    const shimC = generateEffectShimC(mod.effectImports ?? []);
    const soPath = compileToSharedObject("captureRandom", irText, shimC);

    // The body's last expression is `var r`, where `r` is bound to the
    // ptr-returning `nextNumber()` effect call. The IR-level inference
    // (which doesn't know typeclass method signatures) propagates that
    // ptr type to the function's return type. The test reads the boxed
    // double from the returned pointer to assert the underlying value.
    // (A higher-level Phase that brings typeclass-method signatures into
    // type inference would emit `define double @captureRandom()` here.)
    const lib = dlopen(soPath, {
      captureRandom: { args: [], returns: FFIType.ptr },
      fenel_register_handler: {
        args: [FFIType.cstring, FFIType.ptr, FFIType.ptr],
        returns: FFIType.void,
      },
      fenel_reset_handlers: { args: [], returns: FFIType.void },
    });

    const storage = new Map<string, number>();
    const scratch = Buffer.alloc(8);
    const nextNumberCallback = new JSCallback(
      (_envPtr: Pointer | null, _argsPtr: Pointer | null, _n: number): Pointer => {
        scratch.writeDoubleLE(0.42, 0);
        return ptr(scratch);
      },
      { args: [FFIType.ptr, FFIType.ptr, FFIType.i32], returns: FFIType.ptr },
    );
    const setCallback = new JSCallback(
      (_envPtr: Pointer | null, argsPtr: Pointer | null, _n: number): null => {
        const keyPtr = read.ptr(argsPtr as Pointer, 0) as Pointer;
        const valPtr = read.ptr(argsPtr as Pointer, 8) as Pointer;
        const key = new CString(keyPtr).toString();
        const val = read.f64(valPtr, 0);
        storage.set(key, val);
        return null;
      },
      { args: [FFIType.ptr, FFIType.ptr, FFIType.i32], returns: FFIType.ptr },
    );

    lib.symbols.fenel_register_handler(
      Buffer.from("HasCryptoRandom:nextNumber\0"),
      nextNumberCallback.ptr,
      null,
    );
    lib.symbols.fenel_register_handler(
      Buffer.from("HasStateIO:set\0"),
      setCallback.ptr,
      null,
    );
    try {
      const retPtr = lib.symbols.captureRandom() as Pointer;
      // retPtr points at the boxed double allocated inside the
      // `nextNumber` JS callback (the scratch buffer above).
      const r = read.f64(retPtr, 0);
      expect(r).toBe(0.42);
      expect(storage.get("lastRandom")).toBe(0.42);
    } finally {
      lib.symbols.fenel_reset_handlers();
      nextNumberCallback.close();
      setCallback.close();
      lib.close();
      try {
        fs.rmSync(path.dirname(soPath), { recursive: true, force: true });
      } catch {
        // Best-effort cleanup.
      }
    }
  });
});
